properties.query:
// Is a Table offline for longer than One Hour
// Set allowable offline interval, Lower interval default = 1hr, upper default = 2h(+5m covers any gaps in alerting), Severity=Low
let lowerInterval = 1h;
let upperInterval = 2h + 5m;
let safeline = datatable (Type: string, Message:string, TimeGenerated:datetime)['safeline','QC',"2022-01-01"]; 
union isfuzzy=true Syslog, CommonSecurityLog, safeline
| where Type !="safeline"
| summarize LastCall = max(TimeGenerated), minutesSinceLastCall=datetime_diff("minute", now(), max(TimeGenerated)) by Type
// Alert if the Agent is down for > n hrs but ignore if down for longer than n hrs so we dont duplicate the Alert.
| where LastCall < ago(lowerInterval) and LastCall > ago(upperInterval)
| project LastCall, minutesSinceLastCall, Type
| join
(
// Count data for the past 7 days to give a daily trend indictaing if this Source is often offline 
union isfuzzy=true Syslog, CommonSecurityLog, safeline
| where Type !="safeline"
| make-series dailyTrend=count() on TimeGenerated from ago(7d) to now() step 1d by Type
)
on Type
| project-away TimeGenerated, Type1
